```cell
const fork = await ctx.call("tevm/fork", { blockTag: "latest" })
const vitalikAddress = "0xd8dA6BF26964aF9D7eEd9e03E53415D37aA96045"
const balance = await ctx.call("tevm/getBalance", { address: vitalikAddress })
const pane = await ctx.call("ui/pane", {
  name: "balance",
  title: "vitalik.eth ETH balance",
  props: { address: vitalikAddress, balanceWei: balance.wei, balanceEther: balance.ether, blockTag: "latest" }
})
console.log(JSON.stringify({ fork, balance, pane }))
```
